cd /home/user/RL_Study/report-gepa/runs/originals/scifi && python3 - <<'EOF'
import json, pandas as pd, numpy as np
facts=json.load(open('facts.json'))
for f in facts:
    env={'pd':pd,'np':np}
    for k,p in f['tables'].items():
        env[k]=pd.read_csv(p)
    print('='*70)
    print(f['id'])
    print('CLAIM:', f['claim'])
    try:
        val=eval(f['code'],env)
        print(val)
    except Exception as e:
        print('ERROR',e)
EOF

